import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
from proxy.tool_protocol import is_tool_protocol_message, has_tool_calling_state


def test_empty_tool_calls_is_protocol():
    assert is_tool_protocol_message({"role": "assistant", "tool_calls": []})
    assert is_tool_protocol_message({"role": "assistant", "tool_calls": None})


def test_plain_assistant_is_not_protocol():
    assert not is_tool_protocol_message({"role": "assistant", "content": "hi"})


def test_body_with_empty_tool_calls_bypasses():
    body = {"messages": [{"role": "user", "content": "x"}, {"role": "assistant", "tool_calls": []}]}
    assert has_tool_calling_state(body)

